head.script:
// 화면 리사이징

scwin.gIsurCd;
scwin.gDate;
scwin.gDepCd;
scwin.gEmpNo;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드 처리
        $c.cm.PanelToGroupBox(panel_1);
        $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
        await scwin.setCode();
        $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
        // fn_Search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF36500.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        // 클릭된 값 변수에 셋팅
        scwin.setContnId(row);
        if (colid === "CEO_CHG" || colid === "LGSHRHD_CHG" || colid === "COM_CHG" || colid === "INQDISCLS_REQ" || colid === "NFAITHDISCLS_CORP" ||
            colid === "CEO_CHG2" || colid === "LGSHRHD_CHG2" || colid === "COM_CHG2" || colid === "INQDISCLS_REQ2" || colid === "NFAITHDISCLS_CORP2" ||
            colid === "CEO_CHG3" || colid === "LGSHRHD_CHG3" || colid === "COM_CHG3" || colid === "INQDISCLS_REQ3" || colid === "NFAITHDISCLS_CORP3" ||
            colid === "CEO_CHG4" || colid === "LGSHRHD_CHG4" || colid === "COM_CHG4" || colid === "INQDISCLS_REQ4" || colid === "NFAITHDISCLS_CORP4") {
            const sAcptNo = dts_list.getCellData(row, "ACPT_NO_" + colid);
            if (sAcptNo !== "" && sAcptNo.length === 14) {
                await $c.stf.openDisclViewer(sAcptNo, 'R');
            }
        } else if (colid === "COM_ABBRV") {
            $c.stf.fn_PopupCorpInfo();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF36500.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF36500.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave('ULDSTF36500.xml', SCREN_PROCS_TP_CD_07);
        const file_name = "횡령배임우려기업 목록";
        const today = $c.ut.cGetToday('yyyymmddhhmmss');
        const xls_path = $c.session.getExcelDownPath() + today + "_" + file_name + ".xlsx";
        $c.data.downloadGridViewOffice(grd_Grid, file_name, xls_path, "8", 0);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF36500.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name dts_qtr_OnLoadCompleted
 * @description dts_qtr 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
