 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_qtr_OnLoadCompleted = async function(rowcount) {
    try {
        cmb_Qtr.setSelectedIndex(1); // 전 분기

        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF36500.dts_qtr_OnLoadCompleted" });
    }
};

